WITH filtered AS (SELECT id, full_name, email, manager_id, job_title, hire_date, is_remote, LAST_DAY(hire_date) hire_date_month_end FROM employees WHERE full_name LIKE 'F%'), enriched AS (SELECT s.id, s.full_name, s.email, s.manager_id, s.hire_date, s.hire_date_month_end, b.hire_date AS employee_hire_date FROM filtered s JOIN employees b ON s.manager_id = b.id WHERE b.salary > 117000), scored AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY manager_id ORDER BY hire_date_month_end, id) row_seq, ROW_NUMBER() OVER (PARTITION BY manager_id ORDER BY hire_date_month_end DESC, id) row_seq_2, ROW_NUMBER() OVER (PARTITION BY manager_id ORDER BY employee_hire_date, id) event_seq, ROW_NUMBER() OVER (ORDER BY hire_date_month_end, id) seq_no FROM enriched), latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY manager_id ORDER BY hire_date_month_end, id) AS latest_rank FROM scored) ranked WHERE latest_rank = 1) SELECT p.job_title, COUNT(*) AS cnt, SUM(e.row_seq_2) AS total_row_seq_2, MAX(e.seq_no) AS max_seq_no, GROUPING_ID() AS gid FROM latest e LEFT JOIN employees p ON e.manager_id = p.id GROUP BY CUBE (p.job_title) ORDER BY cnt DESC NULLS FIRST
